#include "ksVoiceFeedbackTask.h"
#include <iostream>
#include <stdexcept>
static void check(bool b){if(!b)throw std::runtime_error("Voice feedback property failed");}
int main(){using T=ks::VoiceFeedbackTask;uint64_t cases=0;auto verify=[&](bool reset,unsigned cursor,unsigned count,unsigned age,unsigned low,unsigned status,unsigned reply){T t{reset?T::Kind::Reset:T::Kind::Poll};unsigned currentWrites=0,cursorWrites=0,ageWrites=0,lowWrites=0,countReads=0,voices=0,selects=0,statuses=0,replies=0,guard=0;auto next=uint8_t(cursor+1);if(next>=count)next=0;auto slot=uint8_t(cursor+3);bool pending=age&0x8000,active=age!=0,activated=active&&pending&&!(status&1);bool counted=active&&!activated;auto read=[&](T::Read r)->uint32_t{switch(r){case T::Read::Cursor:return cursor;case T::Read::Count:return count;case T::Read::Age:return age;case T::Read::Countdown:++countReads;return low;}return 0;};auto write=[&](T::Write w,uint32_t v){switch(w){case T::Write::Current:check(v==cursor);++currentWrites;break;case T::Write::Cursor:check(v==(reset?0:next));++cursorWrites;break;case T::Write::Activated:check(t.slot()==slot&&activated&&v==0x7fffffff);++ageWrites;break;case T::Write::Age:check(t.slot()==slot&&!pending&&active&&v==((status&8?age&0x4000:0)|(reply>>1)));++ageWrites;break;case T::Write::Countdown:check(t.slot()==slot&&counted&&v==uint16_t(low-1)&&v!=0);++lowWrites;break;}};auto store=[](T::Write w){return w==T::Write::Current?0u:3u;};while(t.stage()!=T::Stage::Complete){check(++guard<64);auto child=t.child();if(child!=T::Child::None){if(child==T::Child::Voice)++voices;if(child==T::Child::Select)++selects;if(child==T::Child::Status)++statuses;if(child==T::Child::Age)++replies;check(t.resumeChild(slot,uint8_t(status),uint16_t(reply)));continue;}auto c=t.nextClocks(store),s=unsigned(t.stage());check(t.advanceBefore(c-1,read,write,store)==0&&unsigned(t.stage())==s);check(t.advanceBefore(c,read,write,store)==c);}check(cursorWrites==1&&currentWrites==unsigned(!reset));if(reset)check(!voices&&!selects&&!ageWrites&&!lowWrites&&!countReads);else check(voices==1&&selects==unsigned(active)&&statuses==unsigned(active)&&replies==unsigned(active&&!pending)&&ageWrites==unsigned(active&&(!pending||activated))&&countReads==unsigned(counted)&&lowWrites==unsigned(counted&&uint16_t(low-1)!=0));++cases;};for(unsigned a=0;a<256;++a)for(unsigned b=0;b<256;++b){verify(false,a,b,0,1,0,0);verify(false,0,14,a*256+b,5,8,0xaaaa);verify(false,0,14,0x4000,a*256+b,8,0xffff);verify(false,0,14,0x4000,5,8,a*256+b);verify(false,0,14,(a&1)?0x8000:0x4000,5,a,b*257);}for(unsigned cursor=0;cursor<256;++cursor)verify(true,cursor,0,0,0,0,0);std::cout<<"PASS: "<<cases<<" pure feedback properties; all cursor/count, full16-bit age/countdown/reply, allstatus/byte-header pairs; pending activation, live age mask, old1countdown remains1, late bound slot, reset and budget refusal\n";}
